#include <vector>

using namespace std;

class Solution {
public:
    bool mergeTriplets(vector<vector<int>>& triplets, vector<int>& target) {
        int tx = target[0], ty = target[1], tz = target[2];
        bool hasX = false, hasY = false, hasZ = false;

        for (const auto& t : triplets) {
            if (t[0] <= tx && t[1] <= ty && t[2] <= tz) {
                if (t[0] == tx) hasX = true;
                if (t[1] == ty) hasY = true;
                if (t[2] == tz) hasZ = true;
            }
        }
        return hasX && hasY && hasZ;
    }
};

class Solution {
    public boolean mergeTriplets(int[][] triplets, int[] target) {
        int tx = target[0], ty = target[1], tz = target[2];
        boolean hasX = false, hasY = false, hasZ = false;

        for (int[] t : triplets) {
            if (t[0] <= tx && t[1] <= ty && t[2] <= tz) {
                if (t[0] == tx) hasX = true;
                if (t[1] == ty) hasY = true;
                if (t[2] == tz) hasZ = true;
            }
        }
        return hasX && hasY && hasZ;
    }
}

/**
 * @param {number[][]} triplets
 * @param {number[]} target
 * @return {boolean}
 */
var mergeTriplets = function(triplets, target) {
    const [tx, ty, tz] = target;
    let hasX = false, hasY = false, hasZ = false;

    for (let i = 0; i < triplets.length; ++i) {
        const [a, b, c] = triplets[i];
        if (a <= tx && b <= ty && c <= tz) {
            if (a === tx) hasX = true;
            if (b === ty) hasY = true;
            if (c === tz) hasZ = true;
        }
    }
    return hasX && hasY && hasZ;
};
